  RETURN NEXT pad || CASE WHEN p_asker IS NULL THEN 'no   you do not hold ' ELSE 'no   they do not hold ' END || 'user.has_blocked';
END $f$;

CREATE FUNCTION authz_int."user__edit__why"(p_id uuid, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."user__edit");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'user.edit = self';
  BEGIN
    v_ok := (p_id) IN (SELECT id FROM authz_int."user__self");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'self';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."user__self__why"(p_id, p_depth + 1, p_seen, p_asker); END IF;
  END;
END $f$;

CREATE FUNCTION authz_int."bot__owner__why"(p_id bigint, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM "ms"."bots" w WHERE w."id" = p_id AND coalesce((active), false)) THEN
    RETURN NEXT pad || 'no   bot ' || p_id || ' fails the type''s where {' || 'active' || '}';
    RETURN;
  END IF;
  IF p_id IN (SELECT r."id" AS id FROM "ms"."bots" r WHERE r."owner_id" = (SELECT authz.uid())) THEN
    RETURN NEXT pad || 'yes  ' || CASE WHEN p_asker IS NULL THEN 'owner: owner_id is you' ELSE 'owner: owner_id is them' END || '';
    RETURN;
  END IF;
  RETURN NEXT pad || CASE WHEN p_asker IS NULL THEN 'no   you do not hold ' ELSE 'no   they do not hold ' END || 'bot.owner';
END $f$;

