CREATE FUNCTION authz_int."chat__invitee__why"(p_id bigint, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF p_id IN (SELECT g.object_id::bigint AS id FROM authz.shares g WHERE g.object_type = 'chat' AND g.relation = 'invitee' AND g.subject_type = 'link' AND g.subject_id = ANY ((SELECT authz.link_hashes())::text[]) AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) THEN
    RETURN NEXT pad || 'yes  ' || 'invitee: shared by a link you presented' || CASE WHEN p_asker IS NULL OR authz_int.asker_sees(p_asker, 'chat', p_id::text, true) THEN coalesce((SELECT concat(' (by ', coalesce(g.created_by, 'an admin'), coalesce(', until ' || g.expires_at, ''), coalesce(', from ' || g.starts_at, ''), coalesce(', caveat ' || g.caveat, ''), ')') FROM authz.shares g WHERE g.object_type = 'chat' AND g.object_id = p_id::text AND g.relation = 'invitee' AND g.subject_type = 'link' AND g.subject_id = ANY ((SELECT authz.link_hashes())::text[]) AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL ORDER BY g.created_at LIMIT 1), '') ELSE '' END;
    RETURN;
  END IF;
  RETURN NEXT pad || CASE WHEN p_asker IS NULL THEN 'no   you do not hold ' ELSE 'no   they do not hold ' END || 'chat.invitee';
END $f$;

CREATE FUNCTION authz_int."chat__read__why"(p_id bigint, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."chat__read");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'chat.read = member or bot';
  BEGIN
    v_ok := (p_id) IN (SELECT id FROM authz_int."chat__member");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'member';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."chat__member__why"(p_id, p_depth + 1, p_seen, p_asker); END IF;
    v_ok := (p_id) IN (SELECT id FROM authz_int."chat__bot");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'bot';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."chat__bot__why"(p_id, p_depth + 1, p_seen, p_asker); END IF;
  END;
END $f$;

CREATE FUNCTION authz_int."chat__post__why"(p_id bigint, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."chat__post");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'chat.post = (member and not blocked and ({not admins_only} or admin)) or bot';
  BEGIN
    v_ok := (p_id) IN (SELECT r."id" AS id FROM "ms"."chats" r
  WHERE r."id" IN (SELECT id FROM authz_int."chat__member")
    AND NOT EXISTS (SELECT 1 FROM (SELECT id FROM authz_int."chat__blocked") x WHERE x.id = r."id")
    AND r."id" IN ((SELECT r."id" AS id FROM "ms"."chats" r WHERE coalesce((not admins_only), false))
  UNION ALL
  (SELECT id FROM authz_int."chat__admin")));
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '(member and not blocked and ({not admins_only} or admin))';
    v_ok := (p_id) IN (SELECT id FROM authz_int."chat__member");
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'member';
    IF v_ok AND v_holds THEN RETURN QUERY SELECT * FROM authz_int."chat__member__why"(p_id, p_depth + 2, p_seen, p_asker); END IF;
    v_ok := (p_id) IN (SELECT r."id" AS id FROM "ms"."chats" r
  WHERE NOT EXISTS (SELECT 1 FROM (SELECT id FROM authz_int."chat__blocked") x WHERE x.id = r."id"));
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'not blocked';
    v_ok := (p_id) IN ((SELECT r."id" AS id FROM "ms"."chats" r WHERE coalesce((not admins_only), false))
  UNION ALL
  (SELECT id FROM authz_int."chat__admin"));
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '({not admins_only} or admin)';
    v_ok := (p_id) IN (SELECT id FROM authz_int."chat__bot");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'bot';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."chat__bot__why"(p_id, p_depth + 1, p_seen, p_asker); END IF;
  END;
END $f$;

