CREATE FUNCTION authz_int."message__read__why"(p_id text, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."message__read");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'message.read = chat.read and {seq > coalesce(ms.joined_seq(chat_id), 0)}';
  BEGIN
    v_ok := (p_id) IN (SELECT ROW(r."chat_id"::bigint, r."seq"::bigint)::text AS id FROM "ms"."messages" r
  WHERE (r."chat_id", r."seq") IN (SELECT (k.k)."chat_id", (k.k)."seq" FROM (SELECT x.id::authz_gen."message__key" AS k FROM (SELECT id FROM authz_int."message__chat__read") x) k)
    AND authz_int."message__check_522cac4d84"((r.*)::"ms"."messages"));
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '(chat.read and {seq > coalesce(ms.joined_seq(chat_id), 0)})';
    v_ok := (p_id) IN (SELECT id FROM authz_int."message__chat__read");
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'chat.read';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."chat__read" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."chat_id" AS id FROM "ms"."messages" r WHERE (r."chat_id", r."seq") = (((p_id)::authz_gen."message__key")."chat_id", ((p_id)::authz_gen."message__key")."seq") AND r."chat_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the one asking can't see: nothing about it, or above it
      IF NOT authz_int.asker_sees(p_asker, 'chat', v_t.id, false) THEN
        RETURN NEXT pad || '  ' || '       ' || 'chat is a chat you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'chat is chat '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has read' ELSE ', without read' END;
      IF NOT ('chat:read:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND v_holds) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        RETURN QUERY SELECT * FROM authz_int."chat__read__why"(v_t.id::bigint, p_depth + 2 + 1, p_seen || ('chat:read:' || v_t.id), p_asker);
      END IF;
    END LOOP;
    v_ok := (p_id) IN (SELECT ROW(r."chat_id"::bigint, r."seq"::bigint)::text AS id FROM "ms"."messages" r WHERE authz_int."message__check_522cac4d84"((r.*)::"ms"."messages"));
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '{seq > coalesce(ms.joined_seq(chat_id), 0)}';
  END;
END $f$;

CREATE FUNCTION authz_int."message__edit__why"(p_id text, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."message__edit");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'message.edit = sender and {not deleted and created_at > now() - interval ''15 minutes''}';
  BEGIN
    v_ok := (p_id) IN (SELECT ROW(r."chat_id"::bigint, r."seq"::bigint)::text AS id FROM "ms"."messages" r
  WHERE (r."chat_id", r."seq") IN (SELECT (k.k)."chat_id", (k.k)."seq" FROM (SELECT x.id::authz_gen."message__key" AS k FROM (SELECT id FROM authz_int."message__sender") x) k)
    AND coalesce((not deleted and created_at > now() - interval '15 minutes'), false));
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '(sender and {not deleted and created_at > now() - interval ''15 minutes''})';
    v_ok := (p_id) IN (SELECT id FROM authz_int."message__sender");
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'sender';
    IF v_ok AND v_holds THEN RETURN QUERY SELECT * FROM authz_int."message__sender__why"(p_id, p_depth + 2, p_seen, p_asker); END IF;
    v_ok := (p_id) IN (SELECT ROW(r."chat_id"::bigint, r."seq"::bigint)::text AS id FROM "ms"."messages" r WHERE coalesce((not deleted and created_at > now() - interval '15 minutes'), false));
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '{not deleted and created_at > now() - interval ''15 minutes''}';
  END;
END $f$;

CREATE FUNCTION authz_int."message__remove__why"(p_id text, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."message__remove");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'message.remove = sender or chat.manage';
  BEGIN
    v_ok := (p_id) IN (SELECT id FROM authz_int."message__sender");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'sender';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."message__sender__why"(p_id, p_depth + 1, p_seen, p_asker); END IF;
    v_ok := (p_id) IN (SELECT id FROM authz_int."message__chat__manage");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'chat.manage';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."chat__manage" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."chat_id" AS id FROM "ms"."messages" r WHERE (r."chat_id", r."seq") = (((p_id)::authz_gen."message__key")."chat_id", ((p_id)::authz_gen."message__key")."seq") AND r."chat_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the one asking can't see: nothing about it, or above it
      IF NOT authz_int.asker_sees(p_asker, 'chat', v_t.id, false) THEN
        RETURN NEXT pad || '       ' || 'chat is a chat you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'chat is chat '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has manage' ELSE ', without manage' END;
      IF NOT ('chat:manage:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND NOT v_done) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        v_done := true; RETURN QUERY SELECT * FROM authz_int."chat__manage__why"(v_t.id::bigint, p_depth + 1 + 1, p_seen || ('chat:manage:' || v_t.id), p_asker);
      END IF;
    END LOOP;
  END;
END $f$;

